/// A tintable app icon from virgil's set. Pass [color] to tint the
/// icon (tabs: gold when selected, muted otherwise); without a color
/// the PNG renders with its baked-in colors.
class AppIconImage extends StatelessWidget {
  const AppIconImage(this.icon, {super.key, this.size = 24, this.color});

  final AppIcon icon;
  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final image = Image.memory(
      base64Decode(_iconBase64[icon]!),
      width: size,
      height: size,
      gaplessPlayback: true,
    );
    final tint = color;
    if (tint == null) return image;
    return ColorFiltered(
      colorFilter: ColorFilter.mode(tint, BlendMode.srcIn),
      child: image,
    );
  }
}
